    const sizes = String(arg ?? '')
      .split('-')
      .map(Number)
      .filter((n) => n > 0);
    const digits = s.replaceAll(/\D/g, '');
    if (sizes.length === 0) return s;
    if (digits.length !== sizes.reduce((a, b) => a + b, 0)) return s;
